<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px}h1{font-size:18px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:5px}th{background:#eee}.stats{margin-bottom:12px}</style></head><body><h1>Rapport CODIR</h1><div class="stats">Total : {{ $stats['total'] }} | À faire : {{ $stats['a_faire'] }} | En cours : {{ $stats['en_cours'] }} | Terminées : {{ $stats['termine'] }} | En retard : {{ $stats['en_retard'] }}</div><table><thead><tr><th>Réunion</th><th>Activité</th><th>Tâche</th><th>Responsables</th><th>Début</th><th>Fin</th><th>Statut</th></tr></thead><tbody>@foreach($taches as $t)<tr><td>{{ $t->reunion?->titre }}</td><td>{{ $t->activite?->titre }}</td><td>{{ $t->titre }}</td><td>{{ $t->users->map(fn($u)=>$u->nom_complet)->implode(', ') }}</td><td>{{ $t->date_debut?->format('d/m/Y') }}</td><td>{{ $t->date_fin?->format('d/m/Y') }}</td><td>{{ $t->statut }}</td></tr>@endforeach</tbody></table></body></html>
